import React, { useEffect, useMemo, useState } from 'react'
import { Navigate, NavLink, useNavigate, useParams } from 'react-router-dom'
import { Activity, ArrowLeft, BarChart3, Bot, Building2, CalendarDays, CheckCircle2, ChevronRight, CircleAlert, Eye, EyeOff, LayoutDashboard, LogIn, LogOut, MessageCircle, Plus, Search, Settings, ShieldCheck, UserRound, Users, Wifi, XCircle } from 'lucide-react'
import { supabase } from '../lib/supabase'
import { useTenant } from '../contexts/TenantContext'
import { Empty, TenantPage, getSupabase, localDateKey, localDateTimeToUtc, utcToLocalInput, formatZoned, BR_TIMEZONE, zonedParts } from './shared'

function PatientsPage(){
  const{activeCompany}=useTenant(); const[items,setItems]=useState<any[]>([]); const[loading,setLoading]=useState(true);
  const[open,setOpen]=useState(false); const[detail,setDetail]=useState<any>(null); const[history,setHistory]=useState<any[]>([]);
  const[editing,setEditing]=useState<any>(null); const[name,setName]=useState(''); const[phone,setPhone]=useState(''); const[whatsapp,setWhatsapp]=useState(''); const[status,setStatus]=useState<'active'|'inactive'>('active'); const[search,setSearch]=useState(''); const[error,setError]=useState(''); const[busy,setBusy]=useState(false);
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);const{data,error}=await supabase!.from('patients').select('*').eq('company_id',activeCompany.id).order('full_name');if(error)setError(error.message);setItems(data||[]);setLoading(false)}
  useEffect(()=>{load()},[activeCompany?.id]);
  function openNew(){setEditing(null);setName('');setPhone('');setWhatsapp('');setStatus('active');setError('');setOpen(true)}
  function openEdit(p:any){setEditing(p);setName(p.full_name||'');setPhone(p.phone||'');setWhatsapp(p.whatsapp||'');setStatus(p.status==='inactive'?'inactive':'active');setError('');setOpen(true)}
  async function openDetail(p:any){setDetail(p);setHistory([]);setError('');if(!supabase||!activeCompany)return;const{data,error}=await supabase!.from('appointments').select('*,professionals(name)').eq('company_id',activeCompany.id).eq('patient_id',p.id).order('starts_at',{ascending:false});if(error)setError(error.message);setHistory(data||[])}
  async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;setBusy(true);setError('');const payload={full_name:name.trim(),phone:phone.trim()||null,whatsapp:whatsapp.trim()||null,status};const result=editing?await supabase!.from('patients').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase!.from('patients').insert({company_id:activeCompany.id,...payload});if(result.error)setError(result.error.message);else{setOpen(false);await load()}setBusy(false)}
  const filtered=items.filter(p=>String(p.full_name||'').toLowerCase().includes(search.toLowerCase())||String(p.whatsapp||p.phone||'').includes(search));
  return <TenantPage title="Pacientes" description="Cadastro, contato e histórico dos pacientes." action={<button className="hero-btn" onClick={openNew}><Plus size={16}/> Novo paciente</button>}>
    <section className="panel"><div className="head"><div><h2>Pacientes</h2><p>{items.length} cadastro(s)</p></div><input style={{maxWidth:280}} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nome ou telefone..."/></div>
    {error&&<div className="form-error">{error}</div>}
    {loading?<div className="empty-box">Carregando...</div>:filtered.length===0?<div className="empty-box"><Users size={35}/><h2>{items.length?'Nenhum resultado':'Nenhum paciente'}</h2><p>{items.length?'Tente outro nome ou telefone.':'Cadastre o primeiro paciente deste consultório.'}</p></div>:filtered.map(p=><div className="row" key={p.id}><UserRound size={18}/><span><b>{p.full_name}</b><small>{p.whatsapp||p.phone||'Sem telefone'}</small></span><i>{p.status==='active'?'Ativo':'Inativo'}</i><button className="back-link" onClick={()=>openDetail(p)}>Ver histórico</button><button className="back-link" onClick={()=>openEdit(p)}>Editar</button></div>)}</section>
    {open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar paciente':'Novo paciente'}</h2><p>Dados básicos e status do cadastro.</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome completo*<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Telefone<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>WhatsApp<input value={whatsapp} onChange={e=>setWhatsapp(e.target.value)}/></label>{editing&&<label>Status<select value={status} onChange={e=>setStatus(e.target.value as 'active'|'inactive')}><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label>}</div>{error&&<div className="form-error">{error}</div>}<button className="hero-btn" disabled={busy}>{busy?'Salvando...':editing?'Salvar alterações':'Salvar paciente'}</button></form></div>}
    {detail&&<div className="modal-backdrop"><div className="modal panel"><div className="head"><div><h2>{detail.full_name}</h2><p>{detail.whatsapp||detail.phone||'Sem telefone cadastrado'}</p></div><button className="icon-btn" onClick={()=>setDetail(null)}><XCircle size={18}/></button></div><h3>Histórico de atendimentos</h3>{history.length===0?<div className="empty-box">Nenhum atendimento encontrado.</div>:history.map(a=><div className="row" key={a.id}><CalendarDays size={18}/><span><b>{formatZoned(a.starts_at,activeCompany?.timezone||BR_TIMEZONE)}</b><small>{a.professionals?.name||'Profissional'} · {a.appointment_type||'Consulta'}</small></span><i>{a.status}</i></div>)}<button className="back-link" onClick={()=>setDetail(null)}>Fechar</button></div></div>}
  </TenantPage>
}
function ProfessionalsPage(){
  const{activeCompany}=useTenant(); const[items,setItems]=useState<any[]>([]); const[loading,setLoading]=useState(true); const[open,setOpen]=useState(false); const[detail,setDetail]=useState<any>(null); const[history,setHistory]=useState<any[]>([]);
  const[editing,setEditing]=useState<any>(null); const[name,setName]=useState(''); const[specialty,setSpecialty]=useState(''); const[registration,setRegistration]=useState(''); const[status,setStatus]=useState<'active'|'inactive'>('active'); const[search,setSearch]=useState(''); const[error,setError]=useState(''); const[busy,setBusy]=useState(false);
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);const{data,error}=await supabase!.from('professionals').select('*').eq('company_id',activeCompany.id).order('name');if(error)setError(error.message);setItems(data||[]);setLoading(false)}
  useEffect(()=>{load()},[activeCompany?.id]);
  function openNew(){setEditing(null);setName('');setSpecialty('');setRegistration('');setStatus('active');setError('');setOpen(true)}
  function openEdit(p:any){setEditing(p);setName(p.name||'');setSpecialty(p.specialty||'');setRegistration(p.professional_registration||'');setStatus(p.status==='inactive'?'inactive':'active');setError('');setOpen(true)}
  async function openDetail(p:any){setDetail(p);setHistory([]);if(!supabase||!activeCompany)return;const{data,error}=await supabase!.from('appointments').select('*,patients(full_name)').eq('company_id',activeCompany.id).eq('professional_id',p.id).order('starts_at',{ascending:false});if(error)setError(error.message);setHistory(data||[])}
  async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;setBusy(true);setError('');const payload={name:name.trim(),specialty:specialty.trim()||null,professional_registration:registration.trim()||null,status};const result=editing?await supabase!.from('professionals').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase!.from('professionals').insert({company_id:activeCompany.id,...payload});if(result.error)setError(result.error.message);else{setOpen(false);await load()}setBusy(false)}
  const filtered=items.filter(p=>String(p.name||'').toLowerCase().includes(search.toLowerCase())||String(p.specialty||'').toLowerCase().includes(search.toLowerCase())||String(p.professional_registration||'').toLowerCase().includes(search.toLowerCase()));
  return <TenantPage title="Profissionais" description="Equipe, especialidades e agenda de atendimento." action={<button className="hero-btn" onClick={openNew}><Plus size={16}/> Novo profissional</button>}>
    <section className="panel"><div className="head"><div><h2>Equipe</h2><p>{items.length} profissional(is)</p></div><input style={{maxWidth:300}} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nome, especialidade..."/></div>
    {error&&<div className="form-error">{error}</div>}{loading?<div className="empty-box">Carregando...</div>:filtered.length===0?<div className="empty-box"><UserRound size={35}/><h2>{items.length?'Nenhum resultado':'Nenhum profissional'}</h2><p>{items.length?'Tente outro termo.':'Cadastre o primeiro profissional deste consultório.'}</p></div>:filtered.map(p=><div className="row" key={p.id}><UserRound size={18}/><span><b>{p.name}</b><small>{p.specialty||'Especialidade não informada'} {p.professional_registration?'· '+p.professional_registration:''}</small></span><i>{p.status==='active'?'Ativo':'Inativo'}</i><button className="back-link" onClick={()=>openDetail(p)}>Ver agenda</button><button className="back-link" onClick={()=>openEdit(p)}>Editar</button></div>)}</section>
    {open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar profissional':'Novo profissional'}</h2><p>Dados usados na Agenda e nos atendimentos.</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome*<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Especialidade<input value={specialty} onChange={e=>setSpecialty(e.target.value)}/></label><label>Registro profissional<input value={registration} onChange={e=>setRegistration(e.target.value)}/></label><label>Status<select value={status} onChange={e=>setStatus(e.target.value as 'active'|'inactive')}><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label></div>{error&&<div className="form-error">{error}</div>}<button className="hero-btn" disabled={busy}>{busy?'Salvando...':editing?'Salvar alterações':'Salvar profissional'}</button></form></div>}
    {detail&&<div className="modal-backdrop"><div className="modal panel"><div className="head"><div><h2>{detail.name}</h2><p>{detail.specialty||'Especialidade não informada'}</p></div><button className="icon-btn" onClick={()=>setDetail(null)}><XCircle size={18}/></button></div><h3>Atendimentos</h3>{history.length===0?<div className="empty-box">Nenhum atendimento encontrado.</div>:history.map(a=><div className="row" key={a.id}><CalendarDays size={18}/><span><b>{new Date(a.starts_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</b><small>{a.patients?.full_name||'Paciente'} · {a.appointment_type||'Consulta'}</small></span><i>{a.status}</i></div>)}<button className="back-link" onClick={()=>setDetail(null)}>Fechar</button></div></div>}
  </TenantPage>
}
function AgendaPage(){
  const{activeCompany}=useTenant();
  const[today,setToday]=useState(()=>new Date());
  const[view,setView]=useState<'day'|'week'|'month'|'list'>('month');
  const[items,setItems]=useState<any[]>([]);const[patients,setPatients]=useState<any[]>([]);const[pros,setPros]=useState<any[]>([]);
  const[open,setOpen]=useState(false);const[editing,setEditing]=useState<any>(null);
  const[patient,setPatient]=useState('');const[professional,setProfessional]=useState('');const[date,setDate]=useState('');const[time,setTime]=useState('');const[duration,setDuration]=useState('60');const[type,setType]=useState('Consulta');const[notes,setNotes]=useState('');const[status,setStatus]=useState('scheduled');const[error,setError]=useState('');const[loading,setLoading]=useState(true);
  const[search,setSearch]=useState('');const[filterProfessional,setFilterProfessional]=useState('');const[filterStatus,setFilterStatus]=useState('');
  const tz=activeCompany?.timezone||BR_TIMEZONE;const dayKey=localDateKey(today,tz);
  const range=useMemo(()=>{if(view==='day'||view==='list')return{start:dayKey,end:dayKey};if(view==='week'){const d=new Date(today);const w=d.getDay()||7;d.setDate(d.getDate()-w+1);const e=new Date(d);e.setDate(e.getDate()+6);return{start:localDateKey(d,tz),end:localDateKey(e,tz)}}const first=new Date(today.getFullYear(),today.getMonth(),1);const last=new Date(today.getFullYear(),today.getMonth()+1,0);return{start:localDateKey(first,tz),end:localDateKey(last,tz)}},[today,dayKey,tz,view]);
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);setError('');const from=localDateTimeToUtc(range.start+'T00:00',tz);const endDate=new Date(range.end+'T12:00:00');endDate.setDate(endDate.getDate()+1);const to=localDateTimeToUtc(localDateKey(endDate,tz)+'T00:00',tz);const[a,b,c]=await Promise.all([supabase!.from('appointments').select('*,patients(full_name),professionals(name)').eq('company_id',activeCompany.id).gte('starts_at',from.toISOString()).lt('starts_at',to.toISOString()).order('starts_at'),supabase!.from('patients').select('id,full_name').eq('company_id',activeCompany.id).eq('status','active').order('full_name'),supabase!.from('professionals').select('id,name').eq('company_id',activeCompany.id).eq('status','active').order('name')]);if(a.error)setError(a.error.message);else setItems(a.data||[]);if(b.error)setError(b.error.message);else setPatients(b.data||[]);if(c.error)setError(c.error.message);else setPros(c.data||[]);setLoading(false)}
  useEffect(()=>{async function init(){if(!supabase||!activeCompany)return;const{data,error}=await supabase!.rpc('server_now');if(!error&&data){const k=localDateKey(new Date(data),tz);setToday(new Date(k+'T12:00:00'))}await load()}init()},[activeCompany?.id,tz,range.start,range.end]);
  const filteredItems=useMemo(()=>{const q=search.trim().toLowerCase();return items.filter(a=>{const name=String(a.patients?.full_name||'').toLowerCase();const pro=String(a.professionals?.name||'').toLowerCase();return(!q||name.includes(q))&&(!filterProfessional||a.professional_id===filterProfessional)&&(!filterStatus||a.status===filterStatus)})},[items,search,filterProfessional,filterStatus]);
  function clearFilters(){setSearch('');setFilterProfessional('');setFilterStatus('')}
  function resetForm(slot?:number){setEditing(null);setDate(dayKey);setTime(slot===undefined?'09:00':String(slot).padStart(2,'0')+':00');setPatient('');setProfessional('');setDuration('60');setType('Consulta');setNotes('');setStatus('scheduled');setError('');setOpen(true)}
  function editAppointment(a:any){setEditing(a);const local=utcToLocalInput(a.starts_at,activeCompany?.timezone||BR_TIMEZONE);setDate(local.date);setTime(local.time);setPatient(a.patient_id);setProfessional(a.professional_id);setDuration(String(Math.max(15,Math.round((new Date(a.ends_at).getTime()-new Date(a.starts_at).getTime())/60000))));setType(a.appointment_type||'Consulta');setNotes(a.notes||'');setStatus(a.status||'scheduled');setError('');setOpen(true)}
  async function save(e:React.FormEvent){
    e.preventDefault();if(!supabase||!activeCompany)return;setError('');
    if(!patient||!professional){setError('Selecione paciente e profissional.');return}
    if(!date||!time){setError('Informe data e horário.');return}
    const minutes=Number(duration);
    if(!Number.isFinite(minutes)||minutes<15||minutes>480){setError('A duração deve ficar entre 15 minutos e 8 horas.');return}
    const start=localDateTimeToUtc(date+'T'+time,activeCompany.timezone||BR_TIMEZONE);
    if(Number.isNaN(start.getTime())){setError('Data ou horário inválido.');return}
    const end=new Date(start.getTime()+minutes*60000);
    const now=new Date();
    if(!editing&&start.getTime()<now.getTime()-60000){setError('Não é possível criar atendimento em data e horário passados.');return}
    if(end.getUTCDate()!==start.getUTCDate()&&end.getTime()-start.getTime()<24*60*60*1000){setError('O atendimento não pode ultrapassar a virada do dia.');return}
    const q=supabase!.from('appointments').select('id').eq('company_id',activeCompany.id).eq('professional_id',professional).neq('status','cancelled').lt('starts_at',end.toISOString()).gt('ends_at',start.toISOString());
    const{data:conflict,error:conflictError}=editing?await q.neq('id',editing.id).limit(1):await q.limit(1);
    if(conflictError){setError('Não foi possível validar o horário. Tente novamente.');return}
    if(conflict?.length){setError('Este profissional já possui atendimento neste horário. Escolha outro horário.');return}
    const payload={patient_id:patient,professional_id:professional,starts_at:start.toISOString(),ends_at:end.toISOString(),appointment_type:type,notes:notes.trim()||null,status};
    const result=editing?await supabase!.from('appointments').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase!.from('appointments').insert({company_id:activeCompany.id,...payload});
    if(result.error)setError('Não foi possível salvar o atendimento. Tente novamente.');else{setOpen(false);await load()}
  }
  async function changeStatus(id:string,nextStatus:string){if(!supabase||!activeCompany)return;const{error}=await supabase!.from('appointments').update({status:nextStatus}).eq('id',id).eq('company_id',activeCompany.id);if(error)setError(error.message);else await load()}
  async function remove(id:string){await changeStatus(id,'cancelled')}
  function shiftView(delta:number){setToday(d=>{const n=new Date(d);if(view==='day'||view==='list')n.setDate(n.getDate()+delta);else if(view==='week')n.setDate(n.getDate()+delta*7);else n.setMonth(n.getMonth()+delta);return n})}
  const viewTitle=view==='month'?today.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):view==='week'?(()=>{const d=new Date(today);const w=d.getDay()||7;d.setDate(d.getDate()-w+1);const e=new Date(d);e.setDate(e.getDate()+6);return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})+' — '+e.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})})():today.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});
  const statusNames:any={scheduled:'Agendado',confirmed:'Confirmado',completed:'Realizado',cancelled:'Cancelado'};
  const appointmentCard=(a:any,compact=false)=><div className={compact?'appointment-card compact':'appointment-card'} key={a.id} onClick={()=>editAppointment(a)}><div><b>{formatZoned(a.starts_at,tz,{hour:'2-digit',minute:'2-digit'})} · {a.patients?.full_name||'Paciente'}</b><small>{a.professionals?.name||'Profissional'} · {a.appointment_type||'Consulta'} · {statusNames[a.status]||a.status}</small></div>{!compact&&<span><button type="button" className="back-link" onClick={e=>{e.stopPropagation();editAppointment(a)}}>Editar</button>{a.status!=='confirmed'&&a.status!=='completed'&&<button type="button" className="back-link" onClick={e=>{e.stopPropagation();changeStatus(a.id,'confirmed')}}>Confirmar</button>}{a.status==='confirmed'&&<button type="button" className="back-link" onClick={e=>{e.stopPropagation();changeStatus(a.id,'completed')}}>Concluir</button>}{a.status!=='cancelled'&&a.status!=='completed'&&<button type="button" className="back-link danger" onClick={e=>{e.stopPropagation();remove(a.id)}}>Cancelar</button>}</span>}</div>;
  const renderDay=(key:string,compact=false)=>{
    const dayItems=filteredItems.filter(a=>localDateKey(new Date(a.starts_at),tz)===key).sort((a,b)=>new Date(a.starts_at).getTime()-new Date(b.starts_at).getTime());
    const lanes:any[]=[];
    const placed=dayItems.map(a=>{
      const p=zonedParts(new Date(a.starts_at),tz);
      const end=new Date(a.ends_at);
      const ep=zonedParts(end,tz);
      const startMin=(p.hour-8)*60+p.minute;
      const endMin=Math.max(startMin+15,(ep.hour-8)*60+ep.minute);
      let lane=0;
      while(lanes[lane]!==undefined&&lanes[lane]>startMin)lane++;
      lanes[lane]=endMin;
      const overlap=dayItems.filter(x=>{
        const xp=zonedParts(new Date(x.starts_at),tz), xe=zonedParts(new Date(x.ends_at),tz);
        const xs=(xp.hour-8)*60+xp.minute, xeMin=(xe.hour-8)*60+xe.minute;
        return xs<endMin&&xeMin>startMin;
      }).length;
      return {a,startMin,endMin,lane,overlap};
    });
    const slotHeight=compact?58:72;
    return <div className={compact?'calendar-day compact':'calendar-day'} style={{'--slot-h':slotHeight+'px'} as React.CSSProperties}>
      {Array.from({length:13},(_,i)=>{const hour=8+i;return <div className="calendar-slot" key={hour}><time>{String(hour).padStart(2,'0')}:00</time><div className="slot-content"><button type="button" className="slot-add" onClick={()=>{setToday(new Date(key+'T12:00:00'));resetForm(hour)}} aria-label={'Agendar às '+hour+':00'}>+</button></div></div>})}
      <div className="calendar-events-layer">{placed.map(({a,startMin,endMin,lane,overlap}:any)=>{
        const top=(startMin/60)*slotHeight, height=Math.max(38,((endMin-startMin)/60)*slotHeight-6);
        const width=100/Math.max(1,overlap), left=lane*width;
        return <div key={a.id} className="calendar-event" style={{top,height,left:'calc('+left+'% + 2px)',width:'calc('+width+'% - 6px)'}} onClick={()=>editAppointment(a)}>
          <b>{formatZoned(a.starts_at,tz,{hour:'2-digit',minute:'2-digit'})} · {a.patients?.full_name||'Paciente'}</b>
          <small>{a.professionals?.name||'Profissional'} · {a.appointment_type||'Consulta'}</small>
          <em>{statusNames[a.status]||a.status}</em>
        </div>
      })}</div>
    </div>
  };
  const weekKeys=useMemo(()=>{const d=new Date(today);const w=d.getDay()||7;d.setDate(d.getDate()-w+1);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(x.getDate()+i);return localDateKey(x,tz)})},[today,tz]);
  const monthKeys=useMemo(()=>{const first=new Date(today.getFullYear(),today.getMonth(),1);const start=new Date(first);const w=start.getDay()||7;start.setDate(start.getDate()-w+1);return Array.from({length:42},(_,i)=>{const x=new Date(start);x.setDate(x.getDate()+i);return localDateKey(x,tz)})},[today,tz]);
  const miniMonthKeys=monthKeys;
  const monthLabel=today.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
  const goMonth=(delta:number)=>setToday(d=>{const n=new Date(d);n.setMonth(n.getMonth()+delta);return n});

  return <TenantPage title="Agenda" description="Calendário de atendimentos do consultório." action={<button className="hero-btn" onClick={()=>resetForm()}><Plus size={16}/> Novo atendimento</button>}>
    <section className="panel">
      <div className="agenda-toolbar"><div className="agenda-nav"><button type="button" className="agenda-today" onClick={()=>setToday(new Date())}>Hoje</button><button type="button" className="agenda-nav-btn" onClick={()=>shiftView(-1)} title="Anterior"><ArrowLeft size={18}/></button><button type="button" className="agenda-nav-btn" onClick={()=>shiftView(1)} title="Próximo"><ChevronRight size={18}/></button><label className="agenda-date-picker" title="Selecionar data"><CalendarDays size={17}/><input type="date" value={dayKey} onChange={e=>e.target.value&&setToday(new Date(e.target.value+'T12:00:00'))}/></label></div><h2>{viewTitle}</h2><div className="agenda-views">{(['day','week','month','list'] as const).map(v=><button type="button" key={v} className={view===v?'active':''} onClick={()=>setView(v)}>{v==='day'?'Dia':v==='week'?'Semana':v==='month'?'Mês':'Lista'}</button>)}</div></div>
      <div className="agenda-filters"><label className="agenda-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar paciente..."/></label><label><span>Profissional</span><select value={filterProfessional} onChange={e=>setFilterProfessional(e.target.value)}><option value="">Todos</option>{pros.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label><span>Status</span><select value={filterStatus} onChange={e=>setFilterStatus(e.target.value)}><option value="">Todos</option><option value="scheduled">Agendado</option><option value="confirmed">Confirmado</option><option value="completed">Realizado</option><option value="cancelled">Cancelado</option></select></label>{(search||filterProfessional||filterStatus)&&<button type="button" className="back-link clear-filters" onClick={clearFilters}>Limpar filtros</button>}</div>
      {error&&<div className="form-error">{error}</div>}
      {loading?<div className="agenda-loading"><div><strong>Carregando agenda...</strong><p>Buscando atendimentos, pacientes e profissionais.</p></div></div>:view==='day'?renderDay(dayKey):view==='week'?<div className="agenda-week">{weekKeys.map(k=><div className="agenda-week-day" key={k}><header><b>{new Date(k+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'})}</b><strong>{new Date(k+'T12:00:00').getDate()}</strong></header>{renderDay(k,true)}</div>)}</div>:view==='month'?<div className="agenda-month-layout"><aside className="agenda-mini"><button type="button" className="mini-new" onClick={()=>resetForm()}><Plus size={14}/> Novo atendimento</button><div className="mini-head"><button type="button" className="icon-btn" onClick={()=>goMonth(-1)}><ArrowLeft size={14}/></button><b>{monthLabel}</b><button type="button" className="icon-btn" onClick={()=>goMonth(1)}><ChevronRight size={14}/></button></div><div className="mini-weekdays">{['S','T','Q','Q','S','S','D'].map((d,i)=><b key={i}>{d}</b>)}</div><div className="mini-grid">{miniMonthKeys.map(k=>{const inMonth=k.slice(0,7)===localDateKey(new Date(today.getFullYear(),today.getMonth(),1),tz).slice(0,7);const selected=k===dayKey;const has=filteredItems.some(a=>localDateKey(new Date(a.starts_at),tz)===k);return <button type="button" key={k} className={(!inMonth?'muted ':'')+(selected?'selected ':'')+(has?'has-events':'')} onClick={()=>setToday(new Date(k+'T12:00:00'))}>{new Date(k+'T12:00:00').getDate()}</button>})}</div><div className="mini-summary"><b>Agenda do dia</b><span>{filteredItems.filter(a=>localDateKey(new Date(a.starts_at),tz)===dayKey).length} atendimento(s)</span></div></aside><div className="agenda-month"><div className="month-weekdays">{['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=><b key={d}>{d}</b>)}</div><div className="month-grid">{monthKeys.map(k=>{const dayItems=filteredItems.filter(a=>localDateKey(new Date(a.starts_at),tz)===k);const inMonth=k.slice(0,7)===localDateKey(new Date(today.getFullYear(),today.getMonth(),1),tz).slice(0,7);return <div className={'month-cell '+(!inMonth?'muted':'')+(k===dayKey?' selected':'')} key={k} onClick={()=>{setToday(new Date(k+'T12:00:00'));setView('day')}}><div className="month-cell-head"><strong>{new Date(k+'T12:00:00').getDate()}</strong>{dayItems.length>0&&<span className="month-count">{dayItems.length}</span>}</div><div className="month-events">{dayItems.slice(0,3).map(a=><div key={a.id} className={'month-event status-'+a.status} onClick={e=>{e.stopPropagation();editAppointment(a)}}><b>{formatZoned(a.starts_at,tz,{hour:'2-digit',minute:'2-digit'})}</b> {a.patients?.full_name||'Paciente'}</div>)}{dayItems.length>3&&<small>+ {dayItems.length-3} outros</small>}</div></div>})}</div></div></div>:<div className="agenda-list">{filteredItems.length?filteredItems.map(a=>appointmentCard(a)):<div className="empty-box">Nenhum atendimento encontrado com os filtros atuais.</div>}</div>}
    </section>
    {open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar atendimento':'Novo atendimento'}</h2><p>{date&&new Date(date+'T12:00').toLocaleDateString('pt-BR')} {time&&'· '+time} {duration&&'· '+duration+' min'}</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Paciente*<select required value={patient} onChange={e=>setPatient(e.target.value)}><option value="">Selecione</option>{patients.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>Profissional*<select required value={professional} onChange={e=>setProfessional(e.target.value)}><option value="">Selecione</option>{pros.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Data*<input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label>Hora*<input required type="time" value={time} onChange={e=>setTime(e.target.value)}/></label><label>Tipo<select value={type} onChange={e=>setType(e.target.value)}><option>Consulta</option><option>Retorno</option><option>Avaliação</option><option>Online</option></select></label><label>Duração<select value={duration} onChange={e=>setDuration(e.target.value)}><option value="30">30 min</option><option value="45">45 min</option><option value="60">60 min</option><option value="90">90 min</option><option value="120">120 min</option></select></label><label>Status<select value={status} onChange={e=>setStatus(e.target.value)}><option value="scheduled">Agendado</option><option value="confirmed">Confirmado</option><option value="completed">Realizado</option><option value="cancelled">Cancelado</option></select></label><label className="full-field">Observações<textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={3}/></label></div>{error&&<div className="form-error">{error}</div>}<button type="submit" className="hero-btn">{editing?'Salvar alterações':'Agendar'}</button></form></div>}
  </TenantPage>
}
function WhatsAppPage(){
  const{activeCompany}=useTenant();
  const[item,setItem]=useState<any>(null);
  const[templates,setTemplates]=useState<any[]>([]);
  const[messages,setMessages]=useState<any[]>([]);
  const[loading,setLoading]=useState(true);
  const[busy,setBusy]=useState(false);
  const[error,setError]=useState('');
  const[success,setSuccess]=useState('');
  const[qr,setQr]=useState<string|null>(null);
  const[filter,setFilter]=useState('');

  async function load(){
    if(!supabase||!activeCompany)return;
    setLoading(true);setError('');
    const[w,t,m]=await Promise.all([
      supabase!.from('whatsapp_integrations').select('*').eq('company_id',activeCompany.id).maybeSingle(),
      supabase!.from('message_templates').select('*').eq('company_id',activeCompany.id).order('created_at',{ascending:false}),
      supabase!.from('whatsapp_messages').select('id,recipient_number,direction,kind,body,status,sent_at,created_at').eq('company_id',activeCompany.id).order('created_at',{ascending:false}).limit(50)
    ]);
    if(w.error||t.error||m.error)setError(w.error?.message||t.error?.message||m.error?.message||'Não foi possível carregar o WhatsApp.');
    setItem(w.data||null);setTemplates(t.data||[]);setMessages(m.data||[]);setLoading(false);
  }
  useEffect(()=>{load()},[activeCompany?.id]);

  async function session(action:string){
    if(!supabase)return;
    setBusy(true);setError('');setSuccess('');
    const{data,error}=await supabase!.functions.invoke('manage-evolution-session',{body:{action}});
    if(error){setError(error.message||'Não foi possível comunicar com o WhatsApp.');setBusy(false);return}
    if(data?.error){setError(data.error);setBusy(false);return}
    if(data?.qr){
      const q=data.qr?.value||data.qr?.qr||data.qr?.data||data.qr;
      if(typeof q==='string')setQr(q.startsWith('data:')?q:`data:image/png;base64,${q}`);
    }
    setSuccess(data?.status==='connected'?'WhatsApp conectado.':'Sessão atualizada.');
    await load();setBusy(false);
  }

  useEffect(()=>{
    if(!item||item.status!=='connecting')return;
    const timer=setInterval(()=>session('status'),5000);
    return()=>clearInterval(timer);
  },[item?.status]);

  const statusLabel=item?.status==='connected'?'Conectado':item?.status==='connecting'?'Conectando':item?.status==='error'?'Erro':'Desconectado';
  const filtered=messages.filter(m=>!filter||String(m.recipient_number||'').includes(filter)||String(m.body||'').toLowerCase().includes(filter.toLowerCase()));

  return <TenantPage title="WhatsApp" description="Conecte o WhatsApp do consultório e gerencie mensagens padrão.">
    <section className="panel">
      <div className="head"><div><h2>Conexão</h2><p>Uma sessão WAHA exclusiva para este consultório.</p></div><i>{statusLabel}</i></div>
      {loading?<div className="empty-box">Carregando...</div>:<>
        {item?.status==='connected'&&<div className="wa"><Wifi size={22}/><span><b>{item.phone_number||'WhatsApp conectado'}</b><small>Última sincronização: {item.last_sync_at?formatZoned(item.last_sync_at,activeCompany?.timezone||BR_TIMEZONE):'—'}</small></span></div>}
        {item?.status==='connecting'&&<div className="empty-box"><Wifi size={30}/><h2>Aguardando conexão</h2><p>Escaneie o QR Code no WhatsApp.</p>{qr&&<img src={qr} alt="QR Code para conectar o WhatsApp" style={{width:260,height:260,objectFit:'contain',margin:'16px auto'}}/>}</div>}
        {item?.status!=='connected'&&item?.status!=='connecting'&&<div className="empty-box"><MessageCircle size={30}/><h2>WhatsApp desconectado</h2><p>Conecte uma sessão para habilitar os disparos automáticos.</p></div>}
        {item?.status==='error'&&<div className="form-error">{item.last_error||'Falha na conexão.'}</div>}
        <div><button className="hero-btn" disabled={busy} onClick={()=>session(item?.status==='connecting'?'qr':'start')}>{busy?'Processando...':item?.status==='connected'?'Atualizar status':item?.status==='connecting'?'Atualizar QR':'Conectar WhatsApp'} <Wifi size={16}/></button>{item?.status==='connected'&&<button className="back-link" disabled={busy} onClick={()=>session('start')}>Reconectar</button>}</div>
      </>}
    </section>

    <section className="panel">
      <div className="head"><div><h2>Mensagens padrão</h2><p>Templates reutilizáveis para automações.</p></div><NavLink className="hero-btn" to="/automacoes">Configurar automações</NavLink></div>
      {templates.length===0?<div className="empty-box"><MessageCircle size={30}/><p>Nenhuma mensagem padrão cadastrada.</p></div>:templates.map(t=><div className="row" key={t.id}><MessageCircle size={18}/><span><b>{t.name}</b><small>{t.category} · {t.body}</small></span><i>{t.active?'Ativo':'Inativo'}</i></div>)}
    </section>

    <section className="panel">
      <div className="head"><div><h2>Histórico</h2><p>Últimas mensagens registradas.</p></div><input style={{maxWidth:260}} value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filtrar número ou texto..."/></div>
      {filtered.length===0?<div className="empty-box"><MessageCircle size={30}/><p>Nenhuma mensagem encontrada.</p></div>:filtered.map(m=><div className="row" key={m.id}><MessageCircle size={17}/><span><b>{m.direction==='outbound'?'Enviada':'Recebida'} · {m.recipient_number||'Número não informado'}</b><small>{m.body||'Sem conteúdo'} · {formatZoned(m.created_at,activeCompany?.timezone||BR_TIMEZONE)}</small></span><i>{m.status||'registrada'}</i></div>)}
    </section>
    {error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}
  </TenantPage>
}
function AutomationsPage(){
  const{activeCompany}=useTenant();
  const[items,setItems]=useState<any[]>([]);const[templates,setTemplates]=useState<any[]>([]);const[dispatches,setDispatches]=useState<any[]>([]);
  const[open,setOpen]=useState(false);const[editing,setEditing]=useState<any>(null);const[deleting,setDeleting]=useState<any>(null);
  const[name,setName]=useState('');const[type,setType]=useState('appointment_reminder');const[advance,setAdvance]=useState('1440');const[channel,setChannel]=useState('whatsapp');const[templateId,setTemplateId]=useState('');const[enabled,setEnabled]=useState(true);
  const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[error,setError]=useState('');const[success,setSuccess]=useState('');
  async function load(){if(!supabase||!activeCompany)return;setLoading(true);setError('');const[a,t,d]=await Promise.all([
    supabase!.from('automations').select('*').eq('company_id',activeCompany.id).order('name'),
    supabase!.from('message_templates').select('id,name,active').eq('company_id',activeCompany.id).order('name'),
    supabase!.from('automation_dispatches').select('id,automation_id,appointment_id,recipient_number,status,scheduled_for,sent_at,error_message,created_at').eq('company_id',activeCompany.id).order('created_at',{ascending:false}).limit(50)
  ]);if(a.error||t.error||d.error)setError(a.error?.message||t.error?.message||d.error?.message||'Não foi possível carregar as automações.');setItems(a.data||[]);setTemplates((t.data||[]).filter(x=>x.active));setDispatches(d.data||[]);setLoading(false)}
  useEffect(()=>{load()},[activeCompany?.id]);
  function resetForm(){setEditing(null);setName('');setType('appointment_reminder');setAdvance('1440');setChannel('whatsapp');setTemplateId(templates[0]?.id||'');setEnabled(true);setError('');setSuccess('');setOpen(true)}
  function edit(a:any){setEditing(a);setName(a.name||'');setType(a.type||'appointment_reminder');setAdvance(String(a.advance_minutes??1440));setChannel(a.channel||'whatsapp');const m=templates.find(t=>t.name===a.message_template);setTemplateId(m?.id||'');setEnabled(Boolean(a.enabled));setError('');setSuccess('');setOpen(true)}
  async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;const selected=templates.find(t=>t.id===templateId);if(!name.trim()){setError('Informe um nome para a automação.');return}if(channel==='whatsapp'&&!selected){setError('Selecione um template ativo para o WhatsApp.');return}setSaving(true);setError('');const payload={company_id:activeCompany.id,name:name.trim(),type,advance_minutes:Math.max(0,Number(advance)||0),channel,message_template:selected?.name||'',enabled};const result=editing?await supabase!.from('automations').update(payload).eq('id',editing.id).eq('company_id',activeCompany.id):await supabase!.from('automations').insert(payload);if(result.error)setError(result.error.message);else{setSuccess(editing?'Automação atualizada.':'Automação criada.');setOpen(false);await load()}setSaving(false)}
  async function remove(){if(!supabase||!activeCompany||!deleting)return;const{error}=await supabase!.from('automations').delete().eq('id',deleting.id).eq('company_id',activeCompany.id);if(error)setError(error.message);else{setDeleting(null);setSuccess('Automação excluída.');await load()}}
  async function toggle(a:any){if(!supabase||!activeCompany)return;const{error}=await supabase!.from('automations').update({enabled:!a.enabled}).eq('id',a.id).eq('company_id',activeCompany.id);if(error)setError(error.message);else await load()}
  const pending=dispatches.filter(d=>d.status==='pending'||d.status==='scheduled').length;const sent=dispatches.filter(d=>d.status==='sent'||d.status==='completed').length;const failed=dispatches.filter(d=>d.status==='failed'||d.status==='error').length;
  return <TenantPage title="Automações" description="Regras de lembretes e mensagens automáticas." action={<button className="hero-btn" onClick={resetForm}><Plus size={16}/> Nova automação</button>}>
    <div className="metrics"><Metric label="Ativas" value={items.filter(a=>a.enabled).length} icon={Bot}/><Metric label="Pendentes" value={pending} icon={Activity}/><Metric label="Enviadas" value={sent} icon={CheckCircle2}/><Metric label="Falhas" value={failed} icon={CircleAlert}/></div>
    <section className="panel">{error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}{loading?<div className="empty-box">Carregando automações...</div>:items.length===0?<div className="empty-box"><Bot size={35}/><h2>Nenhuma automação</h2><p>Crie uma regra para lembretes de consulta.</p><button className="hero-btn" onClick={resetForm}><Plus size={16}/> Criar automação</button></div>:items.map(a=><div className="row" key={a.id}><Bot size={18}/><span><b>{a.name}</b><small>{a.advance_minutes>=1440?Math.round(a.advance_minutes/1440)+' dia(s)':a.advance_minutes>=60?Math.round(a.advance_minutes/60)+' hora(s)':a.advance_minutes+' min'} antes · {a.channel} · {a.message_template||'Sem template'}</small></span><i>{a.enabled?'Ativa':'Inativa'}</i><button className="back-link" onClick={()=>edit(a)}>Editar</button><button className="back-link" onClick={()=>toggle(a)}>{a.enabled?'Desativar':'Ativar'}</button><button className="back-link" onClick={()=>setDeleting(a)}>Excluir</button></div>)}</section>
    <section className="panel"><div className="head"><div><h2>Histórico de disparos</h2><p>Últimos eventos registrados pelas automações.</p></div></div>{dispatches.length===0?<div className="empty-box"><Activity size={30}/><p>Nenhum disparo registrado ainda.</p></div>:dispatches.map(d=><div className="row" key={d.id}><Activity size={17}/><span><b>{d.recipient_number||'Número não informado'}</b><small>Agendado: {d.scheduled_for?formatZoned(d.scheduled_for,activeCompany?.timezone||BR_TIMEZONE):'—'}{d.sent_at?' · Enviado: '+formatZoned(d.sent_at,activeCompany?.timezone||BR_TIMEZONE):''}{d.error_message?' · '+d.error_message:''}</small></span><i>{d.status}</i></div>)}</section>
    {deleting&&<div className="modal-backdrop"><div className="modal panel"><h2>Excluir automação?</h2><p>O registro da regra será removido. O histórico de disparos não será apagado.</p><button className="hero-btn" onClick={remove}>Excluir</button> <button className="back-link" onClick={()=>setDeleting(null)}>Cancelar</button></div></div>}
    {open&&<div className="modal-backdrop"><form className="modal panel" onSubmit={save}><div className="head"><div><h2>{editing?'Editar automação':'Nova automação'}</h2><p>Defina quando e qual mensagem será usada.</p></div><button type="button" className="icon-btn" onClick={()=>setOpen(false)}><XCircle size={18}/></button></div><div className="form-grid"><label>Nome*<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Lembrete de consulta"/></label><label>Gatilho<select value={type} onChange={e=>setType(e.target.value)}><option value="appointment_reminder">Lembrete de consulta</option><option value="appointment_confirmation">Confirmação de consulta</option><option value="appointment_followup">Pós-consulta</option></select></label><label>Antecedência<select value={advance} onChange={e=>setAdvance(e.target.value)}><option value="60">1 hora antes</option><option value="120">2 horas antes</option><option value="1440">1 dia antes</option><option value="2880">2 dias antes</option><option value="10080">7 dias antes</option></select></label><label>Canal<select value={channel} onChange={e=>setChannel(e.target.value)}><option value="whatsapp">WhatsApp</option><option value="manual">Manual</option></select></label><label>Mensagem padrão<select value={templateId} onChange={e=>setTemplateId(e.target.value)} disabled={channel!=='whatsapp'}><option value="">Selecione um template</option>{templates.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label>Status<select value={enabled?'active':'inactive'} onChange={e=>setEnabled(e.target.value==='active')}><option value="active">Ativa</option><option value="inactive">Inativa</option></select></label></div>{channel==='whatsapp'&&templates.length===0&&<div className="form-error">Nenhum template ativo. Crie uma mensagem padrão em WhatsApp antes de ativar esta automação.</div>}<div><button className="hero-btn" disabled={saving}>{saving?'Salvando...':editing?'Salvar alterações':'Criar automação'} <CheckCircle2 size={16}/></button> <button type="button" className="back-link" onClick={()=>setOpen(false)}>Cancelar</button></div></form></div>}
  </TenantPage>
}
function TenantSettingsPage(){
  const{activeCompany}=useTenant();
  const[name,setName]=useState('');const[legal,setLegal]=useState('');const[cnpj,setCnpj]=useState('');const[phone,setPhone]=useState('');const[email,setEmail]=useState('');
  const[timezone,setTimezone]=useState('America/Sao_Paulo');const[zip,setZip]=useState('');const[street,setStreet]=useState('');const[number,setNumber]=useState('');const[complement,setComplement]=useState('');const[neighborhood,setNeighborhood]=useState('');const[city,setCity]=useState('');const[state,setState]=useState('');
  const[fullName,setFullName]=useState('');const[loginEmail,setLoginEmail]=useState('');const[newPassword,setNewPassword]=useState('');const[showPassword,setShowPassword]=useState(false);
  const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[error,setError]=useState('');const[success,setSuccess]=useState('');
  useEffect(()=>{async function load(){if(!supabase||!activeCompany)return;setLoading(true);const[{data:c},{data:{user}}]=await Promise.all([supabase!.from('companies').select('*').eq('id',activeCompany.id).maybeSingle(),supabase!.auth.getUser()]);setName(c?.name||'');setTimezone(c?.timezone||'America/Sao_Paulo');setLegal(c?.legal_name||'');setCnpj(c?.cnpj||'');setPhone(c?.phone||'');setEmail(c?.email||'');setZip(c?.zip_code||'');setStreet(c?.street||'');setNumber(c?.number||'');setComplement(c?.complement||'');setNeighborhood(c?.neighborhood||'');setCity(c?.city||'');setState(c?.state||'');setLoginEmail(user?.email||'');if(user){const{data:p}=await supabase!.from('profiles').select('full_name').eq('id',user.id).maybeSingle();setFullName(p?.full_name||'')}setLoading(false)}load()},[activeCompany?.id]);
  async function saveCompany(e:React.FormEvent){e.preventDefault();if(!supabase||!activeCompany)return;setSaving(true);setError('');setSuccess('');const{error}=await supabase!.from('companies').update({name:name.trim(),legal_name:legal||null,cnpj:cnpj||null,phone:phone||null,email:email||null,zip_code:zip||null,street:street||null,number:number||null,complement:complement||null,neighborhood:neighborhood||null,city:city||null,state:state||null}).eq('id',activeCompany.id);if(error)setError(error.message);else setSuccess('Dados do consultório salvos.');setSaving(false)}
  async function saveProfile(e:React.FormEvent){e.preventDefault();if(!supabase)return;setSaving(true);setError('');setSuccess('');const{data:{user}}=await supabase!.auth.getUser();if(!user){setError('Sessão expirada.');setSaving(false);return}const p=await supabase!.from('profiles').upsert({id:user.id,full_name:fullName.trim()},{onConflict:'id'});if(p.error){setError(p.error.message);setSaving(false);return}if(newPassword){const u=await supabase!.auth.updateUser({password:newPassword});if(u.error){setError(u.error.message);setSaving(false);return}}setNewPassword('');setSuccess('Perfil e segurança atualizados.');setSaving(false)}
  if(loading)return <TenantPage title="Configurações" description="Dados do consultório e da conta."><div className="panel">Carregando...</div></TenantPage>;
  return <TenantPage title="Configurações" description="Dados do consultório e da conta.">
    <section className="panel"><div className="head"><div><h2>Consultório</h2><p>Dados exibidos e usados na operação.</p></div></div><form className="form-grid" onSubmit={saveCompany}><label>Nome fantasia*<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Razão social<input value={legal} onChange={e=>setLegal(e.target.value)}/></label><label>CNPJ<input value={cnpj} onChange={e=>setCnpj(e.target.value)}/></label><label>Telefone<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>CEP<input value={zip} onChange={e=>setZip(e.target.value)}/></label><label>Rua<input value={street} onChange={e=>setStreet(e.target.value)}/></label><label>Número<input value={number} onChange={e=>setNumber(e.target.value)}/></label><label>Complemento<input value={complement} onChange={e=>setComplement(e.target.value)}/></label><label>Bairro<input value={neighborhood} onChange={e=>setNeighborhood(e.target.value)}/></label><label>Cidade<input value={city} onChange={e=>setCity(e.target.value)}/></label><label>Estado<input maxLength={2} value={state} onChange={e=>setState(e.target.value.toUpperCase())}/></label><div><button className="hero-btn" disabled={saving}>{saving?'Salvando...':'Salvar dados'} <CheckCircle2 size={16}/></button></div></form></section>
    <section className="panel"><div className="head"><div><h2>Minha conta</h2><p>Atualize seu nome e senha de acesso.</p></div></div><form className="form-grid" onSubmit={saveProfile}><label>Nome completo<input value={fullName} onChange={e=>setFullName(e.target.value)}/></label><label>E-mail de login<input disabled value={loginEmail}/></label><label>Nova senha<div className="password-wrap"><input type={showPassword?'text':'password'} minLength={8} value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="Deixe vazio para manter"/><button type="button" className="icon-btn" onClick={()=>setShowPassword(v=>!v)}>{showPassword?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label><div><button className="hero-btn" disabled={saving}>{saving?'Salvando...':'Salvar conta'} <CheckCircle2 size={16}/></button></div></form></section>
    {error&&<div className="form-error">{error}</div>}{success&&<div className="form-success">{success}</div>}
  </TenantPage>
}
function TenantDashboard(){const{activeCompany}=useTenant();const navigate=useNavigate();const[stats,setStats]=useState({today:0,confirmed:0,pending:0,done:0,patients:0,professionals:0});const[next,setNext]=useState<any[]>([]);const[wa,setWa]=useState<any>(null);useEffect(()=>{async function load(){if(!supabase||!activeCompany)return;const{data:serverNow,error:clockError}=await supabase!.rpc('server_now');if(clockError||!serverNow)return;const tz=activeCompany.timezone||BR_TIMEZONE;const dayKey=localDateKey(new Date(serverNow),tz);const start=localDateTimeToUtc(dayKey+'T00:00',tz);const end=localDateTimeToUtc(dayKey+'T23:59',tz);end.setTime(end.getTime()+60000);const [ap,pa,pr,wi]=await Promise.all([supabase!.from('appointments').select('id,starts_at,status,patients(full_name),professionals(name)').eq('company_id',activeCompany.id).gte('starts_at',start.toISOString()).lt('starts_at',end.toISOString()).order('starts_at'),supabase!.from('patients').select('*',{count:'exact',head:true}).eq('company_id',activeCompany.id),supabase!.from('professionals').select('*',{count:'exact',head:true}).eq('company_id',activeCompany.id),supabase!.from('whatsapp_integrations').select('status,phone_number').eq('company_id',activeCompany.id).maybeSingle()]);const list=ap.data||[];setNext(list.slice(0,5));setStats({today:list.length,confirmed:list.filter(x=>x.status==='confirmed').length,pending:list.filter(x=>x.status==='scheduled'||x.status==='pending').length,done:list.filter(x=>x.status==='completed'||x.status==='done').length,patients:pa.count||0,professionals:pr.count||0});setWa(wi.data||null)}load()},[activeCompany?.id]);return <div className="content"><div className="head"><div><h1>Dashboard</h1><p>{activeCompany?.name}</p></div><button className="hero-btn" onClick={()=>navigate('/agenda')}><Plus size={16}/> Novo atendimento</button></div><div className="metrics"><Metric label="Consultas hoje" value={stats.today} icon={CalendarDays}/><Metric label="Confirmadas" value={stats.confirmed} icon={CheckCircle2}/><Metric label="Pendentes" value={stats.pending} icon={Activity}/><Metric label="Realizadas" value={stats.done} icon={CheckCircle2}/></div><div className="grid"><section className="panel"><div className="head"><div><h2>Próximos atendimentos</h2><p>Agenda de hoje</p></div><button className="back-link" onClick={()=>navigate('/agenda')}>Ver agenda</button></div>{next.length===0?<Empty text="Nenhum atendimento para hoje."/>:next.map(a=><div className="row" key={a.id}><CalendarDays size={17}/><span><b>{new Intl.DateTimeFormat('pt-BR',{timeZone:activeCompany?.timezone||BR_TIMEZONE,hour:'2-digit',minute:'2-digit'}).format(new Date(a.starts_at))} · {a.patients?.full_name||'Paciente'}</b><small>{a.professionals?.name||'Profissional'} · {a.status}</small></span></div>)}</section><section className="panel"><h2>Resumo do consultório</h2><div className="stats"><div><b>{stats.patients}</b><small>pacientes</small></div><div><b>{stats.professionals}</b><small>profissionais</small></div></div><div className="wa" style={{marginTop:12}}><MessageCircle size={20}/><span><b>{wa?.status||'WhatsApp não conectado'}</b><small>{wa?.phone_number||'Configure o número da empresa.'}</small></span></div></section></div></div>}
export { PatientsPage, ProfessionalsPage, AgendaPage, WhatsAppPage, AutomationsPage, TenantSettingsPage, TenantDashboard }
